import { useRef, type KeyboardEvent } from "react";
import "./AccentPicker.css";

export type Accent = "myelin" | "emerald" | "amber" | "rose";

const ACCENTS: readonly { id: Accent; label: string }[] = [
  { id: "myelin", label: "Myelin blue" },
  { id: "emerald", label: "Emerald" },
  { id: "amber", label: "Amber" },
  { id: "rose", label: "Rose" },
];

export interface AccentPickerProps {
  value: Accent;
  onChange: (accent: Accent) => void;
}

export function AccentPicker({ value, onChange }: AccentPickerProps) {
  const buttonRefs = useRef<Array<HTMLButtonElement | null>>([]);
  const selectedIndex = Math.max(
    0,
    ACCENTS.findIndex((accent) => accent.id === value),
  );

  function select(index: number) {
    const next = ACCENTS[index];
    if (!next) return;
    onChange(next.id);
    buttonRefs.current[index]?.focus();
  }

  function handleKeyDown(event: KeyboardEvent<HTMLButtonElement>, index: number) {
    let target: number;
    switch (event.key) {
      case "ArrowRight":
      case "ArrowDown":
        target = (index + 1) % ACCENTS.length;
        break;
      case "ArrowLeft":
      case "ArrowUp":
        target = (index - 1 + ACCENTS.length) % ACCENTS.length;
        break;
      case "Home":
        target = 0;
        break;
      case "End":
        target = ACCENTS.length - 1;
        break;
      default:
        return;
    }
    event.preventDefault();
    select(target);
  }

  return (
    <div role="radiogroup" aria-label="Accent colour" className="accent-picker">
      {ACCENTS.map((accent, index) => {
        const checked = accent.id === value;
        return (
          <button
            key={accent.id}
            ref={(element) => {
              buttonRefs.current[index] = element;
            }}
            type="button"
            role="radio"
            aria-checked={checked}
            tabIndex={index === selectedIndex ? 0 : -1}
            className="accent-picker__option"
            data-accent={accent.id}
            onClick={() => select(index)}
            onKeyDown={(event) => handleKeyDown(event, index)}
          >
            <span className="accent-picker__swatch" aria-hidden="true" />
            <span className="accent-picker__label">{accent.label}</span>
          </button>
        );
      })}
    </div>
  );
}
