  border-radius: 999px;
  background: var(--ap-surface);
  color: var(--ap-text);
  font: inherit;
  font-size: 0.9375rem;
  line-height: 1.2;
  cursor: pointer;
  transition:
    background-color 150ms ease,
    border-color 150ms ease;
}

.accent-picker__option:hover {
  background: var(--ap-surface-hover);
}

.accent-picker__option[aria-checked="true"] {
  border-color: var(--ap-selected-border);
