  outline: none;
}

.accent-picker__option:focus-visible {
  outline: 2px solid var(--ap-focus);
  outline-offset: 2px;
}

.accent-picker__swatch {
  flex: none;
  width: 1.25rem;
  height: 1.25rem;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.12);
}

.accent-picker__option[data-accent="myelin"] .accent-picker__swatch {
  background: var(--ap-myelin);
}

.accent-picker__option[data-accent="emerald"] .accent-picker__swatch {
  background: var(--ap-emerald);
}

.accent-picker__option[data-accent="amber"] .accent-picker__swatch {
  background: var(--ap-amber);
}

.accent-picker__option[data-accent="rose"] .accent-picker__swatch {
  background: var(--ap-rose);
}

.accent-picker__option[aria-checked="true"] .accent-picker__label::after {
  content: "\2713";
  margin-left: 0.5rem;
  color: var(--ap-muted);
  font-weight: 600;
}

.accent-picker__label {
  white-space: nowrap;
}

@media (prefers-reduced-motion: reduce) {
  .accent-picker__option {
    transition: none;
  }
}
